401	    @Transactional
402	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
403	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
404	        // and a period closed at the same moment is seen.
405	        Sheet sheet = sheets.lock(sheetId)
406	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
407	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
408	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
409	        refuseIfClosed(sheetId, claim.getDate());
410	        if (!claim.getStatus().canBecome(next)) {
411	            throw new ResponseStatusException(HttpStatus.CONFLICT,
412	                    "A " + claim.getStatus() + " claim cannot become " + next);
413	        }
414	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
415	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
416	        }
417	        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
418	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
419	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
420	        claim.setStatus(next);
421	        claim.setNumber(number);
422	        if (next == ClaimStatus.OPEN) {
423	            claim.setOpenedBy(user);
424	        }
425	        List<String> extra = new ArrayList<>();
426	        if (next == ClaimStatus.SETTLED) {
427	            BigDecimal due = sheet.liveDue(rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
428	                    .map(rate -> sheet.dueAt(claim.getAmount(), rate.getRate(), claim.getDate()))
429	                    .orElse(null), claim.getDate(), claim.isCorrection());
430	            refuseIfOverClerkLimit(sheet, user, due);
431	            claim.setSettledDue(due);
432	            extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
