463	        BigDecimal limit = sheet.getClerkLimit();
464	        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
465	            return;
466	        }
467	        if (due == null || due.compareTo(limit) > 0) {
468	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
469	                    "A clerk cannot settle a claim with a due above " + limit.toPlainString());
470	        }
