474	    private void refuseIfClosed(String sheetId, LocalDate date) {
475	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
476	                .filter(period -> period.isClosed() && period.contains(date))
477	                .findFirst()
478	                .ifPresent(period -> {
479	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
480	                });
