515	/**
516	 * A claim's status. It starts as DRAFT, can be opened and then settled; a DRAFT or OPEN claim can
517	 * be voided. SETTLED and VOID are final. Only OPEN and SETTLED claims count toward the totals.
518	 */
519	public enum ClaimStatus {
520	    DRAFT, OPEN, SETTLED, VOID;
521	
522	    /** Whether a claim in this status counts toward the totals. */
523	    public boolean counts() {
524	        return this == OPEN || this == SETTLED;
525	    }
526	
527	    /** Whether a claim in this status may move to the given one. */
528	    public boolean canBecome(ClaimStatus next) {
529	        return switch (next) {
530	            case OPEN -> this == DRAFT;
531	            case SETTLED -> this == OPEN;
532	            case VOID -> this == DRAFT || this == OPEN;
533	            case DRAFT -> false;
534	        };
535	    }
