971	    public Person add(String sheetId, String user, String name, String grade) {
972	        sheets.load(sheetId, user);
973	        String trimmed = name.trim();
974	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
975	            throw nameInUse();
976	        }
977	        Person person = people.save(new Person(sheetId, trimmed, grade));
