985	
986	    /**
987	     * How many people an import added and how many existing ones it updated, or the lines that
988	     * stopped it (then nothing is changed).
989	     */
990	    public record ImportResult(int added, int updated, List<ImportError> errors) {
991	    }
992	
993	    /**
994	     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
995	     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
996	     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
997	     * recorded from the sheet's today and any other name is added. Blank lines are skipped.
998	     */
999	    @Transactional
1000	    public ImportResult importPeople(String sheetId, String user, String text) {
1001	        String[] lines = text.split("\\r?\\n", -1);
1002	        List<ImportError> errors = new ArrayList<>();
1003	        List<String[]> rows = new ArrayList<>();
1004	        Set<String> seen = new HashSet<>();
1005	        for (int i = 0; i < lines.length; i++) {
1006	            String line = lines[i];
1007	            if (line.isBlank()) {
1008	                continue;
1009	            }
1010	            int number = i + 1;
1011	            int comma = line.lastIndexOf(',');
1012	            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
1013	            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
1014	            String error = null;
1015	            if (name.isEmpty()) {
1016	                error = "Enter a name.";
1017	            } else if (name.length() > MAX_NAME) {
1018	                error = "The name is too long.";
1019	            } else if (!GRADES.contains(grade)) {
1020	                error = "The grade must be A, B or C.";
1021	            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
1022	                error = "That name is repeated in the import.";
1023	            }
1024	            if (error != null) {
1025	                errors.add(new ImportError(number, error));
1026	            } else {
1027	                rows.add(new String[] {name, grade});
1028	            }
1029	        }
1030	        if (!errors.isEmpty()) {
1031	            return new ImportResult(0, 0, errors);
1032	        }
1033	        LocalDate today = null;
1034	        if (!rows.isEmpty()) {
1035	            sheets.load(sheetId, user);
1036	            today = sheets.today(sheetId);
1037	        }
1038	        int added = 0;
1039	        int updated = 0;
1040	        for (String[] row : rows) {
1041	            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
1042	            if (existing.isPresent()) {
1043	                Person person = existing.get();
1044	                person.setGradeFrom(today, row[1]);
1045	                person = people.saveAndFlush(person);
1046	                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + row[1]);
1047	                updated++;
1048	            } else {
1049	                Person person = people.save(new Person(sheetId, row[0], row[1]));
1050	                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + row[1]);
