299	
300	/**
301	 * Loads sheets by id; a sheet never loaded before is created empty. The real clock is read only
302	 * here, to start a new sheet's "today"; everything else uses {@link #today(String)}.
303	 */
304	@Service
305	public class SheetService {
306	
307	    private final SheetRepository sheets;
308	    private final Audit audit;
309	    private final Clock clock = Clock.systemDefaultZone();
310	
311	    public SheetService(SheetRepository sheets, Audit audit) {
312	        this.sheets = sheets;
313	        this.audit = audit;
314	    }
315	
316	    @Transactional
317	    public Sheet load(String id, String user) {
318	        return sheets.findById(id).orElseGet(() -> create(id, user));
319	    }
320	
321	    /** The sheet's "today": the date every decision and default date in the sheet uses. */
322	    @Transactional(readOnly = true)
323	    public LocalDate today(String id) {
324	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
325	    }
326	
327	    @Transactional
328	    public Sheet setToday(String id, String user, LocalDate today) {
329	        Sheet sheet = load(id, user);
330	        sheet.setToday(today);
331	        return sheet;
332	    }
333	
334	    /**
335	     * Change the sheet's clerk limit (two decimals; null for no limit), floor (two decimals; null
336	     * leaves it as it is) terms (days; null leaves them as they are) and late percent (two
337	     * decimals; null leaves it as it is) and policy date (empty for none, the sheet's today; null
338	     * leaves it as it is). Each change is recorded as
339	     * SETTING_CHANGED key=&lt;key&gt; value=&lt;value&gt;, clerk-limit first, then floor, then terms, then late-pct,
340	     * then policy-date, the clerk limit's value empty for no limit and the policy date's empty for none;
341	     * setting a value it already has records nothing.
342	     */
343	    @Transactional
344	    public Sheet setSettings(String id, String user, BigDecimal limit, BigDecimal floor, Integer terms,
345	            BigDecimal latePct, Optional<LocalDate> policyDate) {
346	        load(id, user);
347	        Sheet sheet = sheets.findLockedById(id).orElseThrow();
348	        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
349	        if (!Objects.equals(sheet.getClerkLimit(), scaled)) {
350	            sheet.setClerkLimit(scaled);
351	            audit.change("SETTING_CHANGED", id, user, "key=clerk-limit",
352	                    "value=" + (scaled == null ? "" : scaled.toPlainString()));
353	        }
354	        if (floor != null) {
355	            BigDecimal scaledFloor = floor.setScale(2, RoundingMode.UNNECESSARY);
356	            if (scaledFloor.compareTo(sheet.getFloor()) != 0) {
357	                sheet.setFloor(scaledFloor);
358	                audit.change("SETTING_CHANGED", id, user, "key=floor", "value=" + scaledFloor.toPlainString());
359	            }
360	        }
361	        if (terms != null && terms != sheet.getTerms()) {
362	            sheet.setTerms(terms);
363	            audit.change("SETTING_CHANGED", id, user, "key=terms", "value=" + terms);
364	        }
365	        if (latePct != null) {
366	            BigDecimal scaledPct = latePct.setScale(2, RoundingMode.UNNECESSARY);
367	            if (scaledPct.compareTo(sheet.getLatePct()) != 0) {
368	                sheet.setLatePct(scaledPct);
369	                audit.change("SETTING_CHANGED", id, user, "key=late-pct", "value=" + scaledPct.toPlainString());
370	            }
371	        }
372	        if (policyDate != null && !Objects.equals(sheet.getPolicyDate(), policyDate.orElse(null))) {
373	            sheet.setPolicyDate(policyDate.orElse(null));
374	            audit.change("SETTING_CHANGED", id, user, "key=policy-date",
375	                    "value=" + policyDate.map(LocalDate::toString).orElse(""));
376	        }
377	        return sheet;
378	    }
379	
380	    /**
381	     * The sheet, locked until the caller's transaction ends, so changes that must happen one at a
382	     * time on a sheet (such as giving out claim numbers) do; empty if the sheet was never loaded.
383	     */
384	    @Transactional
385	    public Optional<Sheet> lock(String id) {
386	        return sheets.findLockedById(id);
387	    }
388	
389	    private Sheet create(String id, String user) {
390	        try {
391	            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock)));
392	        } catch (DataIntegrityViolationException e) {
393	            // Another user loaded the same new sheet at the same moment.
394	            return sheets.findById(id).orElseThrow(() -> e);
395	        }
396	    }
