654	            }
655	            if (other.overlaps(from, to)) {
656	                throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps " + other.getName());
657	            }
658	        }
659	        Period period = periods.save(new Period(sheetId, name, from, to));
660	        audit.change("PERIOD_ADDED", sheetId, user, "period=" + name, "from=" + from, "to=" + to);
661	        return period;
662	    }
663	
664	    /**
665	     * Close a period, fixing its due-total: the dues of the counted claims dated in it (an open claim of a
666	     * person on hold is not counted), each a settled
667	     * claim's fixed due or else its amount at its person's grade's rate in force on its date, rounded
668	     * half to even to cents and raised to the sheet's floor, an overdue one's late charge added; a claim with no such rate adds nothing. A closed period cannot be closed again (409).
669	     */
670	    @Transactional
671	    public Period close(String sheetId, String user, String name) {
672	        sheets.load(sheetId, user);
673	        // Lock the sheet, so no claim changes while the total is taken.
674	        Sheet sheet = sheets.lock(sheetId).orElseThrow();
675	        Period period = periods.findBySheetIdAndName(sheetId, name)
676	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
677	        if (period.isClosed()) {
678	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed");
679	        }
680	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
681	                .collect(Collectors.toMap(Person::getId, Function.identity()));
682	        BigDecimal total = BigDecimal.ZERO.setScale(2);
683	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
684	            Person person = byId.get(claim.getPersonId());
685	            if (person == null || !person.counts(claim.getStatus()) || !period.contains(claim.getDate())) {
686	                continue;
687	            }
688	            BigDecimal due = switch (claim.getStatus()) {
689	                case SETTLED -> claim.getSettledDue();
690	                default -> sheet.liveDue(rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
691	                        .map(rate -> sheet.dueAt(claim.getAmount(), rate.getRate(), claim.getDate()))
692	                        .orElse(null), claim.getDate(), claim.isCorrection());
693	            };
694	            if (due != null) {
695	                total = total.add(due);
696	            }
697	        }
698	        period.close(total);
699	        audit.change("PERIOD_CLOSED", sheetId, user, "period=" + period.getName(), "total=" + total.toPlainString());
700	        return period;
701	    }
702	
703	    /**
704	     * Reopen a closed period, making its due-total live again. Only a steward can reopen one (403); a period
705	     * that is not closed cannot be reopened (409).
706	     */
707	    @Transactional
708	    public Period reopen(String sheetId, String user, String name) {
709	        sheets.load(sheetId, user);
710	        // Lock the sheet, so a period is not reopened twice at the same moment.
711	        sheets.lock(sheetId);
712	        Period period = periods.findBySheetIdAndName(sheetId, name)
713	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
714	        if (roles.of(sheetId, user) != Role.STEWARD) {
715	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reopen a period");
716	        }
717	        if (!period.isClosed()) {
718	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed");
719	        }
720	        period.reopen();
721	        audit.change("PERIOD_REOPENED", sheetId, user, "period=" + period.getName());
722	        return period;
723	    }
724	}
