1095	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
1096	                .filter(rate -> rate.getFrom() == null || !rate.getFrom().isAfter(date))
1097	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
