1133	
1134	/**
1135	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
1136	 * so tests can assert side-effects by reading that file — the second test-assertion channel
1137	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
1138	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
1139	 *
1140	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
1141	 * SYNC) so a test reads the record immediately.
1142	 */
1143	@Service
1144	public class Audit {
1145	
1146	    private final Path file;
1147	
1148	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
1149	        this.file = Path.of(path);
1150	    }
1151	
1152	    /** Append one audit record. Tests assert the exact line(s) in the file. */
1153	    public synchronized void record(String entry) {
1154	        try {
1155	            Path parent = file.toAbsolutePath().getParent();
1156	            if (parent != null) {
1157	                Files.createDirectories(parent);
1158	            }
1159	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
1160	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
1161	        } catch (IOException e) {
1162	            throw new UncheckedIOException(e);
1163	        }
1164	    }
1165	
1166	    /**
1167	     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
1168	     * the fields, separated by single spaces. Inside a transaction the record is written only once
1169	     * it commits, so a change that is refused or rolled back writes nothing.
1170	     */
1171	    public void change(String event, String sheetId, String user, String... fields) {
1172	        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
1173	        for (String field : fields) {
1174	            entry.append(' ').append(field);
1175	        }
1176	        String line = entry.toString();
1177	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
1178	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
1179	                @Override
1180	                public void afterCommit() {
1181	                    record(line);
1182	                }
1183	            });
1184	        } else {
1185	            record(line);
1186	        }
1187	    }
1188	
1189	    /** Truncate the audit file. */
1190	    public synchronized void clear() {
1191	        try {
1192	            Files.deleteIfExists(file);
1193	        } catch (IOException e) {
1194	            throw new UncheckedIOException(e);
1195	        }
1196	    }
1197	}
